 {"id": "PEDS-C1-045", "sec": "Post Natal Assessment", "page": 3, "q": "Abundant lanugo in ENBS physical maturity corresponds to a score of ___", "opts": ["2", "1", "-1", "0"], "ans": 1, "exp": "Lanugo: none = -1, sparse = 0, abundant = 1, thinning = 2, bald areas = 3, mostly bald = 4. (Book p3)", "type": "fill"},
 {"id": "PEDS-C1-046", "sec": "Post Natal Assessment", "page": 3, "q": "'Mostly bald' lanugo corresponds to a score of ___", "opts": ["5", "3", "4", "2"], "ans": 2, "exp": "Lanugo: mostly bald = 4. (Book p3)", "type": "fill"},
