 {"id": "PEDS-C1-048", "sec": "Post Natal Assessment", "page": 3, "q": "Creases over the entire sole in ENBS correspond to a score of ___", "opts": ["4", "2", "1", "3"], "ans": 0, "exp": "Plantar surface: 4 = creases over entire sole. (Book p3)", "type": "fill"},
 {"id": "PEDS-C1-049", "sec": "Post Natal Assessment", "page": 3, "q": "A raised areola with a 3-4 mm bud in ENBS is scored ___", "opts": ["3", "4", "2", "5"], "ans": 1, "exp": "Breast: 3 = stippled areola, 1-2 mm bud; 4 = raised areola, 3-4 mm bud; 5 = full areola, 5-10 mm bud. (Book p3)", "type": "fill"},
 {"id": "PEDS-C1-050", "sec": "Post Natal Assessment", "page": 3, "q": "A full areola with a 5-10 mm bud in ENBS is scored 5.", "opts": ["True", "False"], "ans": 0, "exp": "True — Breast: 5 = full areola, 5-10 mm bud. (Book p3)", "type": "tf"},
 {"id": "PEDS-C1-051", "sec": "Post Natal Assessment", "page": 3, "q": "A physical maturity rating of 10 corresponds to ___", "opts": ["26 weeks", "32 weeks", "30 weeks", "28 weeks"], "ans": 3, "exp": "Maturity rating: 10 -> 28 weeks. (Book p3)", "type": "fill"},
 {"id": "PEDS-C1-052", "sec": "Post Natal Assessment", "page": 3, "q": "A maturity rating of -5 corresponds to ___", "opts": ["22 weeks", "20 weeks", "24 weeks", "26 weeks"], "ans": 0, "exp": "Maturity rating: -10 -> 20, -5 -> 22, 0 -> 24 weeks. (Book p3)", "type": "fill"},
 {"id": "PEDS-C1-053", "sec": "Post Natal Assessment", "page": 3, "q": "A maturity rating of 30 corresponds to ___", "opts": ["34 weeks", "36 weeks", "38 weeks", "40 weeks"], "ans": 1, "exp": "Maturity rating: 30 -> 36 weeks. (Book p3)", "type": "fill"},
 {"id": "PEDS-C1-054", "sec": "Post Natal Assessment", "page": 3, "q": "A maturity rating of 45 corresponds to ___", "opts": ["40 weeks", "44 weeks", "42 weeks", "38 weeks"], "ans": 2, "exp": "Maturity rating: 45 -> 42 weeks; 50 -> 44 weeks. (Book p3)", "type": "fill"},
 {"id": "PEDS-C1-055", "sec": "Differences Preterm & Term", "page": 4, "q": "A preterm baby typically shows posture of limbs that is ___", "opts": ["Opisthotonus", "Rigid and fixed", "Flexed (normal tone)", "Extended"], "ans": 3, "exp": "Preterm: extended (down tone); term: flexed (normal tone). (Book p4) (reduced tone)", "type": "fill"},
 {"id": "PEDS-C1-056", "sec": "Differences Preterm & Term", "page": 4, "q": "In the square window test, a preterm baby's fingers ___", "opts": ["Do not touch the forearm", "Cannot flex at all", "Touch the forearm (flexible wrist)", "Cross the midline"], "ans": 0, "exp": "Preterm: fingers do not touch forearm (down flexibility); term: finger touches forearm. (Book p4) (reduced flexibility)", "type": "fill"},
 {"id": "PEDS-C1-057", "sec": "Differences Preterm & Term", "page": 4, "q": "Arm recoil in a preterm baby is ___", "opts": ["Exaggerated", "Absent", "Asymmetric", "Present"], "ans": 1, "exp": "Arm recoil: preterm absent, term present. (Book p4)", "type": "fill"},
 {"id": "PEDS-C1-058", "sec": "Differences Preterm & Term", "page": 4, "q": "A positive scarf sign in a preterm baby means shoulder is hyperextended.", "opts": ["True", "False"], "ans": 1, "exp": "False — correct: Elbow crosses midline. Scarf sign: preterm - elbow crosses midline (d/t down tone, up resistance). (Book p4) (reduced tone, increased resistance)", "type": "tf"},
 {"id": "PEDS-C1-059", "sec": "Differences Preterm & Term", "page": 4, "q": "The popliteal angle (angle between thigh and leg when flexed) is obtuse in ___", "opts": ["Both", "Neither", "Term baby", "Preterm baby"], "ans": 3, "exp": "Popliteal angle: preterm obtuse, term acute. (Book p4)", "type": "fill"},
 {"id": "PEDS-C1-060", "sec": "Differences Preterm & Term", "page": 4, "q": "In a preterm baby, the heel can ___", "opts": ["Reach the ear", "Only touch the shoulder", "Not be adducted", "Not reach the ear"], "ans": 0, "exp": "Heel to ear: preterm possible, term not possible. (Book p4)", "type": "fill"},
 {"id": "PEDS-C1-061", "sec": "Differences Preterm & Term", "page": 4, "q": "In a term baby, the heel-to-ear movement is ___", "opts": ["Painful", "Not possible", "Possible", "Partial only"], "ans": 1, "exp": "Heel to ear: term - not possible. (Book p4)", "type": "fill"},
 {"id": "PEDS-C1-062", "sec": "Differences Preterm & Term", "page": 4, "q": "Breast buds measuring less than 5 mm are typical of ___", "opts": ["Macrosomia", "Term baby", "Preterm baby", "Both"], "ans": 2, "exp": "Breast buds: preterm < 5 mm, term > 5 mm. (Book p4)", "type": "fill"},
 {"id": "PEDS-C1-063", "sec": "Differences Preterm & Term", "page": 4, "q": "External genitalia of a preterm female neonate show ___", "opts": ["Hypertrophied clitoris", "Only labia majora seen (labia minora hidden)", "Fused labia majora", "Both labia majora and labia minora seen"], "ans": 3, "exp": "Preterm female: both labia majora and labia minora seen. (Book p4)", "type": "fill"},
 {"id": "PEDS-C1-064", "sec": "Differences Preterm & Term", "page": 4, "q": "External genitalia of a term female neonate show ___", "opts": ["Only labia majora seen", "Fused labia majora", "Absent labia", "Both labia majora and labia minora seen"], "ans": 0, "exp": "Term female: only labia majora seen (labia minora hidden). (Book p4)", "type": "fill"},
 {"id": "PEDS-C1-065", "sec": "Differences Preterm & Term", "page": 4, "q": "In a preterm male neonate, the scrotum is less pigmented with empty scrotum.", "opts": ["True", "False"], "ans": 0, "exp": "True — Preterm male: scrotum less pigmented; empty scrotum d/t incomplete descent of testis. (Book p4)", "type": "tf"},
 {"id": "PEDS-C1-066", "sec": "Differences Preterm & Term", "page": 4, "q": "In the term male neonate, the testis is fully descended by ___", "opts": ["40 weeks", "32 weeks", "36 weeks", "34 weeks"], "ans": 2, "exp": "Term male: scrotum contains testis (fully descended by 36 wks). (Book p4)", "type": "fill"},
 {"id": "PEDS-C1-067", "sec": "Differences Preterm & Term", "page": 4, "q": "Lanugo hair in a preterm baby is ___", "opts": ["Absent", "Only on scalp", "Sparse", "Abundant"], "ans": 3, "exp": "Lanugo: preterm abundant, term less/absent. (Book p4)", "type": "fill"},
 {"id": "PEDS-C1-068", "sec": "Differences Preterm & Term", "page": 4, "q": "Ear pinna recoil is slow in a preterm baby because ___", "opts": ["Elastic cartilage is poorly developed", "The ear is swollen", "Neck muscles are spastic", "The pinna is fused"], "ans": 0, "exp": "Ear pinna recoil: preterm slow (d/t poorly developed elastic cartilage), term fast. (Book p4)", "type": "fill"},
 {"id": "PEDS-C1-069", "sec": "Complications of Preterm Birth", "page": 4, "q": "Respiratory distress syndrome (RDS) in the preterm is due to ___", "opts": ["Infection", "Surfactant deficiency", "Aspiration", "Bone fracture"], "ans": 1, "exp": "D/t organ immaturity: RDS d/t surfactant deficiency. (Book p4)", "type": "fill"},
 {"id": "PEDS-C1-070", "sec": "Complications of Preterm Birth", "page": 4, "q": "Necrotizing enterocolitis (NEC) in the preterm is due to ___", "opts": ["Hyperthermia", "Excess nutrient stores", "Organ immaturity", "Maternal hypoglycemia"], "ans": 2, "exp": "NEC is listed under preterm complications d/t organ immaturity. (Book p4)", "type": "fill"},
 {"id": "PEDS-C1-071", "sec": "Complications of Preterm Birth", "page": 4, "q": "Intraventricular hemorrhage in the preterm occurs due to maternal coagulopathy.", "opts": ["True", "False"], "ans": 1, "exp": "False — correct: Bleeding from germinal matrix into ventricles. IVH: d/t bleeding from germinal matrix into ventricles (fragile blood vessels). (Book p4)", "type": "tf"},
 {"id": "PEDS-C1-072", "sec": "Complications of Preterm Birth", "page": 4, "q": "Kernicterus in the preterm occurs because ___", "opts": ["Bilirubin crosses the immature blood-brain barrier", "Tone is reduced", "Iron stores are low", "Surfactant is deficient"], "ans": 0, "exp": "Kernicterus: bilirubin crosses immature blood brain barrier (BBB). (Book p4)", "type": "fill"},
 {"id": "PEDS-C1-073", "sec": "Complications of Preterm Birth", "page": 4, "q": "Kernicterus ultimately causes ___", "opts": ["Liver failure", "Brain damage", "Renal failure", "Cardiac arrest"], "ans": 1, "exp": "Bilirubin crosses immature BBB -> brain damage. (Book p4)", "type": "fill"},
 {"id": "PEDS-C1-074", "sec": "Complications of Preterm Birth", "page": 4, "q": "The increased risk of hypoglycemia in the preterm is due to decreased reserve of nutrients.", "opts": ["True", "False"], "ans": 0, "exp": "True — D/t decreased reserve of nutrients: up risk of hypoglycemia. (Book p4)", "type": "tf"},
 {"id": "PEDS-C1-075", "sec": "Complications of Preterm Birth", "page": 4, "q": "Preterm babies are at increased risk of anemia because ___", "opts": ["Red cell production is excessive", "Feeding is deficient", "Hemolysis always occurs", "Iron stores are low"], "ans": 3, "exp": "Up risk of anaemia (d/t down iron stores). (Book p4)", "type": "fill"},
 {"id": "PEDS-C1-076", "sec": "Complications of Preterm Birth", "page": 4, "q": "Hypothermia in the preterm is due to ___", "opts": ["Decreased defence mechanisms to cold", "Sepsis only", "Excess sweating", "Maternal fever"], "ans": 0, "exp": "Up risk of hypothermia (d/t down defence mechanisms to cold). (Book p4)", "type": "fill"},
