 {"id": "PEDS-C1-111", "sec": "Normal Findings", "page": 5, "q": "Onset of pustular melanosis is ___", "opts": ["1 week after birth", "2 weeks after birth", "> 24 hr after birth", "< 24 hr after birth"], "ans": 3, "exp": "Pustular melanosis: onset < 24 hr after birth. (Book p5)", "type": "fill"},
